const objectStorageEndpoint = env.OBJECT_STORAGE_ENDPOINT || (env.R2_ACCOUNT_ID ? `https://${env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com` : 'http://127.0.0.1:8333');
