api.get('/billing/storage',authenticate,async(req:RequestWithAuth,res)=>{
  if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER','EDITOR']))return;
  const [org,subscription,addons]=await Promise.all([
    admin.from('organizations').select('id,name,storage_limit_bytes,storage_used_bytes,storage_reserved_bytes').eq('id',req.orgId).single(),
    admin.from('subscriptions').select('plan_name,status,current_period_end,gateway_subscription_id').eq('organization_id',req.orgId).maybeSingle(),
    admin.from('storage_addon_purchases').select('id,storage_bytes,amount,status,created_at,paid_at').eq('organization_id',req.orgId).order('created_at',{ascending:false}).limit(20),
  ]);
  const addonTableMissing=addons.error?.code==='PGRST205'||addons.error?.code==='42P01';
  const billingColumnsMissing=subscription.error?.code==='42703';
  if(org.error||!org.data||(subscription.error&&!billingColumnsMissing)||(addons.error&&!addonTableMissing)){res.status(500).json({error:'Could not load storage usage.'});return;}
  const basicSubscription=billingColumnsMissing
    ? await admin.from('subscriptions').select('plan_name,status,current_period_end').eq('organization_id',req.orgId).maybeSingle()
    : subscription;
  if(basicSubscription.error){res.status(500).json({error:'Could not load storage usage.'});return;}
  const checkoutColumns=await admin.from('subscriptions').select('gateway_order_id').limit(1);
  const checkoutReady=!addonTableMissing&&!checkoutColumns.error;
  res.json({storage:org.data,subscription:{...(basicSubscription.data||{status:'PENDING_PAYMENT',current_period_end:null}),plan_name:'Basic'},addons:addons.data||[],includedBytes:BASIC_STORAGE_BYTES,planAmount:49900,billingReady:checkoutReady,billingMessage:checkoutReady?null:'Storage billing setup is incomplete. Apply database migration 012 before starting Basic plan payments.',addonOptions:Object.entries(STORAGE_ADDONS).map(([id,pack])=>({id,bytes:pack.bytes,amount:pack.amount}))});
});
