api.get('/public/portfolio',async(_req,res)=>{
  const {data:profiles,error:profileError}=await admin.from('studio_public_profiles')
    .select('organization_id,public_name,city,specialties').eq('published',true);
  if(profileError){res.status(500).json({error:'Could not load public portfolios.'});return;}
  const profileIds=(profiles||[]).map((profile:any)=>profile.organization_id);
  if(!profileIds.length){res.json({items:[]});return;}
  const {data:organizations,error:organizationError}=await admin.from('organizations')
    .select('id').in('id',profileIds).eq('status','ACTIVE');
  if(organizationError){res.status(500).json({error:'Could not load public portfolios.'});return;}
  const activeIds=(organizations||[]).map((organization:any)=>organization.id);
  if(!activeIds.length){res.json({items:[]});return;}
  const visibleProfiles=new Map((profiles||[]).map((profile:any)=>[profile.organization_id,profile]));
  const {data:rows,error}=await admin.from('studio_portfolio_items')
    .select('id,organization_id,caption,created_at,media(filename,mime_type,preview_object_key,thumbnail_object_key,gallery_id)')
    .in('organization_id',activeIds).order('created_at',{ascending:false}).limit(120);
  if(error){res.status(500).json({error:'Could not load public portfolios.'});return;}
  const items=await Promise.all((rows||[]).map(async(row:any)=>{
    const media=row.media as any;
    const profile=visibleProfiles.get(row.organization_id) as any;
    const key=media?.preview_object_key||media?.thumbnail_object_key;
    if(!profile||!media||!key||!media.mime_type?.toLowerCase().startsWith('image/'))return null;
    try{
      const imageUrl=await getSignedUrl(objectStore,new GetObjectCommand({Bucket:objectStorageBucket,Key:key}),{expiresIn:900});
      return {
        id:row.id,caption:row.caption,imageUrl,
        alt:row.caption||media.filename||'Studio portfolio photograph',
        studio:{name:profile.public_name,city:profile.city,specialties:profile.specialties||[]}
      };
    }catch{return null;}
  }));
  res.json({items:items.filter(Boolean)});
});
api.get('/public/studios',async(_req,res)=>{
  const {data:profiles,error}=await admin.from('studio_public_profiles')
    .select('organization_id,public_name,city,description,specialties,contact_email')
    .eq('published',true).order('public_name');
  if(error){res.status(500).json({error:'Could not load the studio directory.'});return;}
  const ids=(profiles||[]).map(profile=>profile.organization_id);
  if(!ids.length){res.json({studios:[]});return;}
  const {data:organizations,error:organizationError}=await admin.from('organizations')
    .select('id').in('id',ids).eq('status','ACTIVE');
  if(organizationError){res.status(500).json({error:'Could not load the studio directory.'});return;}
  const activeIds=new Set((organizations||[]).map(organization=>organization.id));
  const visibleProfiles=(profiles||[]).filter(profile=>activeIds.has(profile.organization_id));
  if(!visibleProfiles.length){res.json({studios:[]});return;}

  // Use a consented public portfolio image as the studio card image.
  // An image explicitly published to Portfolio may also belong to a private gallery.
  const {data:portfolio,error:portfolioError}=await admin.from('studio_portfolio_items')
    .select('organization_id,created_at,media(filename,mime_type,status,gallery_id,preview_object_key,thumbnail_object_key)')
    .in('organization_id',visibleProfiles.map(profile=>profile.organization_id))
    .order('created_at',{ascending:false}).limit(500);
  if(portfolioError){res.status(500).json({error:'Could not load the studio directory.'});return;}
  const photoByStudio=new Map<string,string>();
  for(const row of portfolio||[]){
    if(photoByStudio.has(row.organization_id))continue;
    const media=row.media as any;
    const key=media?.preview_object_key||media?.thumbnail_object_key;
    if(!media||media.status!=='READY'||!key||!media.mime_type?.toLowerCase().startsWith('image/'))continue;
    try{
      const url=await getSignedUrl(objectStore,new GetObjectCommand({Bucket:objectStorageBucket,Key:key}),{expiresIn:900});
      photoByStudio.set(row.organization_id,url);
    }catch{/* Preserve directory access with its monogram fallback if storage is unavailable. */}
  }
  res.json({studios:visibleProfiles.map(profile=>({...profile,photo_url:photoByStudio.get(profile.organization_id)||null}))});
});
