api.get('/admin/organizations',async(req,res)=>{
  const user=await authorizedUser(req);if(!user){res.status(401).json({error:'Sign in to continue.'});return;}
  const {data:allowed}=await admin.from('platform_admins').select('user_id').eq('user_id',user.id).maybeSingle();if(!allowed){res.status(403).json({error:'Super Admin access required.'});return;}
  const [organizations,subscriptions,addons]=await Promise.all([
    admin.from('organizations').select('id,name,status,created_at,storage_limit_bytes,storage_used_bytes,storage_reserved_bytes').order('created_at',{ascending:false}).limit(500),
    admin.from('subscriptions').select('organization_id,plan_name,status,current_period_end'),
    admin.from('storage_addon_purchases').select('organization_id,storage_bytes,amount,status,paid_at').eq('status','CAPTURED').limit(5000),
  ]);
  const storageAddonsUnavailable=addons.error?.code==='PGRST205'||addons.error?.code==='42P01';
  if(organizations.error||subscriptions.error||(addons.error&&!storageAddonsUnavailable)){res.status(500).json({error:'Could not load studio operations and billing.'});return;}
  const subscriptionByOrg=new Map((subscriptions.data||[]).map((s:any)=>[s.organization_id,s]));
  const addonsByOrg=new Map<string,{bytes:number;amount:number;count:number}>();
  for(const addon of addons.data||[]){const previous=addonsByOrg.get(addon.organization_id)||{bytes:0,amount:0,count:0};previous.bytes+=Number(addon.storage_bytes);previous.amount+=Number(addon.amount);previous.count++;addonsByOrg.set(addon.organization_id,previous);}
  res.json({storageAddonsAvailable:!storageAddonsUnavailable,organizations:(organizations.data||[]).map((o:any)=>({...o,storage_limit_bytes:Number(o.storage_limit_bytes),storage_used_bytes:Number(o.storage_used_bytes),storage_reserved_bytes:Number(o.storage_reserved_bytes),subscription:subscriptionByOrg.get(o.id)||{plan_name:'Basic',status:'PENDING_PAYMENT',current_period_end:null},storageAddons:addonsByOrg.get(o.id)||{bytes:0,amount:0,count:0}}))});
});
