api.post('/studio/portfolio',authenticate,async(req:RequestWithAuth,res)=>{
  if(!allowRoles(req,res,['OWNER','ADMIN']))return;
  if(!await ensureActiveStudio(req.orgId,res))return;
  const parsed=z.object({
    mediaId:z.string().uuid(),
    caption:z.string().trim().max(200).optional(),
    consentConfirmed:z.literal(true)
  }).safeParse(req.body);
  if(!parsed.success){res.status(400).json({error:'Choose an image and confirm you have permission to publish it.'});return;}
  const {data:media}=await admin.from('media')
    .select('id,provider,mime_type,status,preview_object_key,thumbnail_object_key,gallery_id')
    .eq('id',parsed.data.mediaId)
    .eq('organization_id',req.orgId)
    .maybeSingle();
  if(!media||media.status!=='READY'||media.provider!=='R2'||!media.mime_type.toLowerCase().startsWith('image/')){
    res.status(404).json({error:'Choose a ready image from this studio.'});return;
  }
  if(!media.preview_object_key&&!media.thumbnail_object_key){
    res.status(409).json({error:'This image has no web-sized preview yet and cannot be published.'});return;
  }
  const {data:item,error}=await admin.from('studio_portfolio_items').insert({
    organization_id:req.orgId,
    media_id:media.id,
    caption:parsed.data.caption||'',
    publication_consent_at:new Date().toISOString()
  }).select('id,media_id,caption,publication_consent_at,created_at').single();
  if(error){res.status(409).json({error:'This image may already be in the public portfolio.'});return;}
  await admin.from('audit_logs').insert({
    organization_id:req.orgId,
    actor_user_id:req.userId,
    action:'PORTFOLIO_IMAGE_PUBLISHED',
    target_type:'media',
    target_id:media.id,
    details:{portfolio_item_id:item.id}
  });
  res.status(201).json({item});
});
api.delete('/studio/portfolio/:id',authenticate,async(req:RequestWithAuth,res)=>{
  if(!allowRoles(req,res,['OWNER','ADMIN']))return;
  const {data:item,error}=await admin.from('studio_portfolio_items')
    .delete()
    .eq('id',req.params.id)
    .eq('organization_id',req.orgId)
    .select('id,media_id')
    .maybeSingle();
  if(error||!item){res.status(404).json({error:'Portfolio image not found.'});return;}
  await admin.from('audit_logs').insert({
    organization_id:req.orgId,
    actor_user_id:req.userId,
    action:'PORTFOLIO_IMAGE_UNPUBLISHED',
    target_type:'media',
    target_id:item.media_id,
    details:{portfolio_item_id:item.id}
  });
  res.json({ok:true});
});
