api.put('/studio/profile',authenticate,async(req:RequestWithAuth,res)=>{if(!allowRoles(req,res,['OWNER','ADMIN']))return;const p=z.object({publicName:z.string().trim().min(2).max(140),city:z.string().max(120).optional(),description:z.string().max(2000).optional(),specialties:z.array(z.string().max(50)).max(20).optional(),contactEmail:z.string().email().or(z.literal('')).optional(),published:z.boolean()}).safeParse(req.body);if(!p.success){res.status(400).json({error:'Check the studio profile details.'});return;}const {data:org}=await admin.from('organizations').select('status').eq('id',req.orgId).single();if(org?.status!=='ACTIVE'&&p.data.published){res.status(403).json({error:'A studio must be approved before it can appear publicly.'});return;}const {error}=await admin.from('studio_public_profiles').upsert({organization_id:req.orgId,public_name:p.data.publicName,city:p.data.city||'',description:p.data.description||'',specialties:p.data.specialties||[],contact_email:p.data.contactEmail||'',published:p.data.published,updated_at:new Date().toISOString()});if(error){res.status(500).json({error:'Could not save the public profile.'});return;}res.json({ok:true});});
